ria":"inf","nivel":1,"enunciado":"No Excel, cada caixinha onde se digita um dado é uma:","opcoes":["Célula","Página","Slide","Pasta"],"explicacao":"Identificada por coluna e linha, como B3."},{"id":6716,"materia":"inf","nivel":1,"enunciado":"Atualizar sempre o sistema e os programas serve, sobretudo, para:","opcoes":["Corrigir falhas de segurança","Deixar a tela colorida","Aumentar o espaço do disco","Trocar a senha automaticamente"],"explicacao":"Muitas atualizações fecham brechas usadas por criminosos."},{"id":6717,"materia":"inf","nivel":2,"enunciado":"O spyware é um programa que:","opcoes":["Espiona o usuário e envia dados sem ele saber","Limpa os vírus do computador automaticamente","Melhora a velocidade da internet","Organiza fotos"],"explicacao":"Keyloggers são um tipo de spyware."},{"id":6718,"materia":"ia","nivel":0,"enunciado":"Um chatbot que responde perguntas usando inteligência artificial é um exemplo de:","opcoes":["IA generativa","Hardware","Planilha","Antivírus"],"explicacao":"Ele gera texto novo a partir do que aprendeu."},{"id":6719,"materia":"ia","nivel":1,"enunciado":"Quando uma IA inventa uma informação falsa com toda a confiança, diz-se que ela:","opcoes":["Alucinou","Travou","Formatou","Compilou"],"explicacao":"Por isso as respostas devem ser conferidas."},{"id":6720,"materia":"rl","nivel":0,"enunciado":"Uma equipe tem 12 policiais e 3 viaturas. Quantos policiais vão em cada viatura, igualmente?","opcoes":["4","3","6","9"],"explicacao":"12 ÷ 3 = 4."},{"id":6721,"materia":"rl","nivel":0,"enunciado":"Uma operação começou às 22h e durou 5 horas. Terminou às:","opcoes":["3h","2h","4h","27h"],"explicacao":"22h + 5h = 3h do dia seguinte."},{"id":6722,"materia":"rl","nivel":0,"enunciado":"Quanto é 10% de 450 multas?","opcoes":["45","4,5","450","90"],"explicacao":"450 ÷ 10 = 45."},{"id":6723,"materia":"rl","nivel":0,"enunciado":"Na sequência 5, 10, 15, 20, ..., o próximo número é:","opcoes":["25","30","22","40"],"explicacao":"Soma-se 5 a cada termo."},{"id":6724,"materia":"rl","nivel":1,"enunciado":"O dobro de um número mais 6 é 20. O número é:","opcoes":["7","13","10","8"],"explicacao":"2x + 6 = 20, logo x = 7."},{"id":6725,"materia":"rl","nivel":1,"enunciado":"Um policial correu 2,5 km por dia durante 6 dias. Correu ao todo:","opcoes":["15 km","12,5 km","8,5 km","25 km"],"explicacao":"2,5 × 6 = 15."},{"id":6726,"materia":"rl","nivel":1,"enunciado":"Uma apreensão de 3 kg foi dividida em pacotes de 250 g. Quantos pacotes?","opcoes":["12","10","8","15"],"explicacao":"3.000 ÷ 250 = 12."},{"id":6727,"materia":"rl","nivel":1,"enunciado":"Se todo policial é servidor e Ana é policial, então:","opcoes":["Ana é servidora","Ana não é servidora","Todo servidor é policial","Ana é delegada"],"explicacao":"Silogismo simples."},{"id":6728,"materia":"rl","nivel":2,"enunciado":"A negação de \"Ele estava armado e fugiu\" é:","opcoes":["Ele não estava armado ou não fugiu","Ele não estava armado e não fugiu","Ele estava armado ou fugiu","Ele fugiu desarmado"],"explicacao":"A negação de \"A e B\" é \"não A ou não B\"."},{"id":6729,"materia":"rl","nivel":2,"enunciado":"Numa urna há 3 bolas vermelhas e 7 azuis. A chance de tirar uma vermelha é:","opcoes":["30%","3%","70%","37%"],"explicacao":"3 em 10."},{"id":6730,"materia":"rl","nivel":2,"enunciado":"O salário de R$ 3.000 teve aumento de 8%. Passou a ser:","opcoes":["R$ 3.240","R$ 3.080","R$ 3.800","R$ 2.760"],"explicacao":"3.000 × 1,08 = 3.240."},{"id":6731,"materia":"cont","nivel":0,"enunciado":"Bens e direitos de uma empresa ficam no:","opcoes":["Ativo","Passivo","Patrimônio líquido","Resultado"],"explicacao":"Obrigações ficam no passivo."},{"id":6732,"materia":"ml","nivel":0,"enunciado":"O exame que verifica as lesões de uma vítima de agressão é o:","opcoes":["Exame de corpo de delito","Exame de vista","Teste do pezinho","Hemograma completo"],"explicacao":"Feito pela perícia oficial."},{"id":6733,"materia":"ml","nivel":1,"enunciado":"O afogamento é um tipo de:","opcoes":["Asfixia","Queimadura","Traumatismo craniano","Intoxicação"],"explicacao":"A água impede a respiração."},{"id":6734,"materia":"ml","nivel":2,"enunciado":"As manchas arroxeadas que surgem nas partes mais baixas do cadáver são os:","opcoes":["Livores (hipóstases)","Hematomas de defesa","Sinais de queimadura","Tatuagens de pólvora"],"explicacao":"Formam-se pelo acúmulo de sangue por gravidade."},{"id":6735,"materia":"port","nivel":0,"enunciado":"Complete: \"Os policiais ___ ao local rapidamente.\"","opcoes":["chegaram","chegou","chegamos","chega"],"explicacao":"O verbo concorda com o sujeito no plural."},{"id":6736,"materia":"port","nivel":1,"enunciado":"O plural de \"escrivão\" é:","opcoes":["escrivães","escrivãos","escrivões","escrivãs"],"explicacao":"Como \"capitães\" e \"alemães\"."},{"id":6737,"materia":"port","nivel":2,"enunciado":"Em \"Os documentos foram apreendidos pela polícia\", o verbo está na voz:","opcoes":["Passiva","Ativa","Reflexiva","Recíproca"],"explicacao":"\"Pela polícia\" é o agente da passiva."},{"id":6738,"materia":"port","nivel":2,"enunciado":"Assinale a frase com vírgula correta:","opcoes":["Senhor delegado, o preso chegou","Senhor delegado o preso, chegou","Senhor, delegado o preso chegou","Senhor delegado o, preso chegou"],"explicacao":"O vocativo é separado por vírgula."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('pen','ppen','leg','const','adm','port','rl','inf','dh','est','cont') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
